1	/**
2	 * Tests for `resolvePrUrl` — PR-level detail URL composition (feature 060,
3	 * FR-005, FR-005a, SC-009). Pure function tests; no DOM, no fixtures.
4	 */
5	
6	import {
7	  resolvePrUrl,
8	  type PrUrlPrRecord,
9	  type PrUrlRepositoryEntry,
10	  type PrUrlWebContext,
11	} from "../../../ui/modules/shared/pr-url";
12	import { LOCAL_DASHBOARD_COLLECTION_URI } from "../../../ui/modules/sdk";
13	
14	const CTX: PrUrlWebContext = {
15	  collectionUri: "https://dev.azure.com/acme-org/",
16	};
17	
18	const KNOWN_REPO: PrUrlRepositoryEntry = {
19	  repository_id: "repo-guid-001",
20	  repository_name: "web-app",
21	  project_name: "Frontend",
22	  organization_name: "acme-org",
23	};
24	
25	const OTHER_REPO: PrUrlRepositoryEntry = {
26	  repository_id: "repo-guid-002",
27	  repository_name: "api-server",
28	  project_name: "Backend",
29	  organization_name: "acme-org",
30	};
31	
32	describe("resolvePrUrl (FR-005 / FR-005a)", () => {
33	  describe("named URL form (happy path)", () => {
34	    it("composes the project/_git/repo-name/pullrequest/id form", () => {
35	      const pr: PrUrlPrRecord = { id: 42, repository_id: "repo-guid-001" };
36	      expect(resolvePrUrl(pr, [KNOWN_REPO, OTHER_REPO], CTX)).toBe(
37	        "https://dev.azure.com/acme-org/Frontend/_git/web-app/pullrequest/42",
38	      );
39	    });
40	
41	    it("percent-encodes repository and project names with special chars", () => {
42	      const repo: PrUrlRepositoryEntry = {
43	        repository_id: "repo-guid-003",
44	        repository_name: "iOS App",
45	        project_name: "Mobile Team",
46	        organization_name: "acme-org",
47	      };
48	      const pr: PrUrlPrRecord = { id: 9, repository_id: "repo-guid-003" };
49	      expect(resolvePrUrl(pr, [repo], CTX)).toBe(
50	        "https://dev.azure.com/acme-org/Mobile%20Team/_git/iOS%20App/pullrequest/9",
51	      );
52	    });
53	
54	    it("appends a trailing slash to collectionUri when missing", () => {
55	      const ctxNoSlash: PrUrlWebContext = {
56	        collectionUri: "https://dev.azure.com/acme-org",
57	      };
58	      const pr: PrUrlPrRecord = { id: 1, repository_id: "repo-guid-001" };
59	      expect(resolvePrUrl(pr, [KNOWN_REPO], ctxNoSlash)).toBe(
60	        "https://dev.azure.com/acme-org/Frontend/_git/web-app/pullrequest/1",
61	      );
62	    });
63	  });
64	
65	  describe("numeric-id fallback form (unresolvable repo)", () => {
66	    it("uses the repository_id as the _git segment when repositories is null", () => {
67	      const pr: PrUrlPrRecord = { id: 7, repository_id: "repo-guid-999" };
68	      expect(resolvePrUrl(pr, null, CTX)).toBe(
69	        "https://dev.azure.com/acme-org/_git/repo-guid-999/pullrequest/7",
70	      );
71	    });
72	
73	    it("uses the repository_id as the _git segment when dimension lookup misses", () => {
74	      const pr: PrUrlPrRecord = { id: 7, repository_id: "repo-guid-999" };
75	      expect(resolvePrUrl(pr, [KNOWN_REPO, OTHER_REPO], CTX)).toBe(
76	        "https://dev.azure.com/acme-org/_git/repo-guid-999/pullrequest/7",
77	      );
78	    });
79	
80	    it("falls back when the dimension entry has an empty repository_name", () => {
81	      const blankRepo: PrUrlRepositoryEntry = {
82	        repository_id: "repo-guid-blank",
83	        repository_name: "",
84	        project_name: "Frontend",
85	        organization_name: "acme-org",
86	      };
87	      const pr: PrUrlPrRecord = { id: 15, repository_id: "repo-guid-blank" };
88	      expect(resolvePrUrl(pr, [blankRepo], CTX)).toBe(
89	        "https://dev.azure.com/acme-org/_git/repo-guid-blank/pullrequest/15",
90	      );
91	    });
92	
93	    it("falls back when the dimension entry has an empty project_name", () => {
